const L=(id,slug,title,body)=>({id,theme:id.slice(0,2),slug,title,...body});
export const improvement = [
L('07.01','correction','Correct one result',{
 build:'A corrected experiment summary with the original mistake preserved.', why:'A system can repair an answer during a task without retaining any new method.', start:'A labelled copy of a baseline report containing an incorrect MAE.', budget:'No fits; one main recomputation and report correction, followed by one fresh-session report check for the additional exercise.',
 how:'Self-correction revises a current output using feedback. Here the checker exposes a wrong summary number and the agent replaces it with the value computed from predictions. When the session ends, no procedure has changed unless you explicitly retain one.', predict:'Will correcting this report prevent the same mistake in a new session?',
 steps:[['Expose the mismatch','Make correction depend on evidence.','Recompute MAE from the copied report’s predictions. Show the mismatch and preserve the original report.','The correction has a concrete reason.'],['Correct the output','Change only the current artifact.','Write a corrected report and a short correction note. Do not edit or save a reusable skill. Explain what changed and what did not.','The current report improves while the future procedure stays fixed.']],
 check:'The corrected number matches the predictions. The original and correction note remain. No retained skill change is claimed.', change:'Start a fresh session, where available, with the same fixed procedure and another labelled wrong summary. Inspect and record whether the host also exposes the earlier correction or saved memory. Check the later report without a new model fit and explain why the first correction alone did not guarantee prevention. Label a same-context exercise if a fresh session is unavailable.', takeaways:['Correction can be local to one task.','A better output does not imply retained learning.','Feedback should be connected to the corrected fact.'],
 quiz:[['What changed?','The current report, not the model weights or reusable procedure.'],['What survived automatically?','Only saved artifacts; future use still needs an explicit mechanism.'],['Is self-correction necessarily successful?','No. A revision can introduce a new mistake; check it.'],['What would add persistence?','A retained, versioned rule that a later session reads and applies.']], next:'A reflection can propose that rule, but it needs its own test.'}),
L('07.02','reflection','Test a reflection before trusting it',{
 build:'A reflection that separates observation, explanation, and a proposed future rule.', why:'A plausible story about a failure can be wrong. The story must earn its place in the procedure.', start:'A failed or weak experiment and its trace.', budget:'At most two targeted checks or fits, declared before running.',
 how:'Reflection interprets an attempt. It may identify a failure, suggest a cause, and propose an action. Those are different epistemic roles: the trace is observed; the cause may be inferred; the action is a hypothesis. A useful reflection changes a later decision and survives a test.', predict:'Can an eloquent explanation reduce performance when followed?',
 steps:[['Write a testable reflection','Avoid treating explanation as proof.','Create REFLECTION.md with observed facts, one causal hypothesis, an alternative explanation, and a proposed procedural rule. Use the actual failed trace.','The note makes uncertainty visible.'],['Test the rule','Compare behavior on a new case.','Predeclare one case where the rule should help and one where it might hurt. Execute the relevant check or bounded fit in each. Keep both outcomes before deciding whether to retain the rule.','A reflection can be rejected even when it sounds sensible.']],
 check:'The proposed rule has a falsifying case. Actual outcomes determine retention. The note does not rewrite the history of the failure.', change:'Compare “always use a tree” with the narrow rule on the same two checked cases. Explain any contradiction without adding undeclared fits.', takeaways:['Reflection is a hypothesis about behavior.','Useful advice has conditions and limits.','A convincing narrative is not an experimental result.'],
 quiz:[['Which part of a reflection is directly observed?','The trace and measured outcome; inferred causes require further evidence.'],['Why test a harmful case?','It exposes overgeneralization and tradeoffs that a favorable case can hide.'],['Can a rejected reflection still be useful?','Yes. Its failure narrows what the evidence supports and can guide a better hypothesis.'],['Does writing the reflection train weights?','No. It creates text; parameter learning is a separate mechanism.']], next:'Retain a checked lesson and inspect whether a later task actually uses it.'}),
L('07.03','persistent_learning','Retain and use a lesson',{
 build:'A versioned memory note that changes a later decision.', why:'A saved lesson only matters to future behavior if a later process retrieves and uses it.', start:'A tested reflection, a new case, and a fresh session where available.', budget:'One later task or fit; preserve a no-memory comparison if already available. The additional scope check uses one separately labelled fixture and no extra fit.',
 how:'Learning can be implemented through changed weights, memory, skills, or other retained state. This lab uses external memory. State the mechanism precisely: the host model reads a saved rule. A larger memory file is not evidence of better decisions.', predict:'What would demonstrate use of the memory rather than mere file existence?',
 steps:[['Retain the narrow rule','Preserve scope and evidence.','Write MEMORY-v1.md with the validated rule, when it applies, when it does not, and links to its supporting and failing cases. Keep the original trace separate.','The note retains a bounded lesson, not an unconditional slogan.'],['Apply it later','Trace persistence into behavior.','In a new task context, read MEMORY-v1.md and record the decision it changes before execution. Run the task and compare with the declared no-memory behavior. Label a same-context exercise if a new session is unavailable.','A decision trace supports actual use.']],
 check:'The memory version is identified. A later action is linked to a specific rule. The result distinguishes use from benefit.', change:'Apply the rule to a case outside its stated scope. Predict possible negative transfer before running a small check.', takeaways:['External memory is one form of retained adaptation.','Persistence, use, and benefit are separate claims.','A useful lesson includes its scope.'],
 quiz:[['Did the language-model weights change?','No. The changed state is an external memory artifact.'],['Does reading memory prove it helped?','No. Compare behavior and outcomes with a suitable baseline.'],['What is negative transfer?','A retained lesson harms performance on another case or task.'],['Is persistent learning automatically recursive improvement?','No. The procedure that writes and checks memory may remain fixed.']], next:'Use a fixed improver to revise a task skill and measure its effect.'}),
L('07.04','self_improvement','Improve a task skill with a fixed procedure',{
 build:'A parent and child research skill compared under one unchanged improvement procedure.', why:'A system can improve its solver while the method that creates improvements stays fixed.', start:'A task skill, failed trace, and the canonical improve-research-skill procedure.', budget:'Four fits maximum across matched parent and child comparisons.',
 how:'The task skill chooses ML experiments. The improver reads failures, proposes one skill edit, and tests it. In this lab the improver’s instructions remain unchanged. The modified object is the solver’s research skill, so any benefit is self-improvement under a fixed improver.', predict:'Which file must stay unchanged for this to remain the fixed-improver comparison?',
 steps:[['Propose one skill edit','Target a documented procedural weakness.','Use improve-research-skill. Preserve the parent task skill. Propose one edit based on selection evidence, such as requiring an error-slice diagnosis before the second model choice. Save the unchanged improver hash and child skill.','The proposal identifies its mutable target.'],['Compare the skills','Measure behavior and cost.','Give parent and child the same starting task and two fits each. Record their choices before fitting, retained results, and available total costs. Keep a child that fails acceptance as a rejected candidate.','The comparison may support benefit, harm, or uncertainty.']],
 check:'The improver version remains fixed. The child is actually used. The acceptance decision follows a declared rule and preserves rejected edits.', change:'Edit the improver itself in a separate unexecuted proposal. Explain why this creates a different experiment that needs another comparison.', takeaways:['Self-improvement can target a solver under a fixed improver.','A changed skill must be executed before claiming an effect.','No improvement is a legitimate result.'],
 quiz:[['Which component changes?','The task-level research skill.'],['Which component stays fixed?','The procedure that proposes and evaluates task-skill edits.'],['Does a better solver score prove a better improver?','No. This experiment does not change or compare improvers.'],['Why retain rejected child skills?','They reveal the search process, costs, and failed hypotheses instead of showing only survivors.']], next:'Organization is a different dimension. Let routing change and inspect the consequences.'}),
L('07.05','organization','Let work reorganize under local rules',{
 build:'A small simulation in which queued checks redistribute between two workers.', why:'A system can change its organization without changing any worker’s skill or improving its final quality.', start:'A generated local simulation with two workers and six labelled check jobs. No agent subworkers are required.', budget:'Two main simulations and one optional overhead counterexample; no model fits.',
 how:'Give each simulated worker the same fixed rule: take an available job when idle. A shared queue and different job durations produce a changing assignment. Organization emerges from local scheduling rules. Measure completion time and correctness separately; redistribution can help one and harm another.', predict:'Will dynamic assignment always beat a fixed assignment?',
 steps:[['Run fixed assignment','Create a baseline organization.','Generate a deterministic queue simulation with job durations and expected results. Run a fixed assignment and save the event trace. Label durations as synthetic.','The baseline organization is visible.'],['Allow local reassignment','Observe organization without changing skills.','Run the same jobs with idle workers taking the next available job. Compare assignment, completion time, and lost or duplicate jobs. Keep worker rules fixed.','The organization changes through local interaction, not a rewritten ML solver.']],
 check:'Both runs use the same synthetic jobs and worker capabilities. The trace shows reassignment. Any speed claim is confined to this simulation.', change:'Add a shared-resource bottleneck or communication delay. Predict when dynamic reassignment loses its advantage.', takeaways:['Self-organization concerns changing arrangement or coordination.','Organization and capability improvement are different properties.','Local rules can have global costs.'],
 quiz:[['Did the worker skill improve?','No. The scheduling arrangement changed while worker rules remained fixed.'],['Why label synthetic durations?','They are constructed teaching inputs, not measured production performance.'],['Does a new arrangement guarantee improvement?','No. Bottlenecks, communication, or contention can make it worse.'],['Is this evidence of RSI?','No. No improvement procedure was revised and inherited.']], next:'Study a collective pattern and distinguish emergence from improved intelligence.'}),
L('07.06','emergence','Observe a collective pattern',{
 build:'A labelled simulation that shows how a system-level pattern depends on local interactions.', why:'“Emergent” often gets used as a synonym for impressive. Make the claimed pattern and mechanism observable.', start:'The queue simulation and a small local-rule extension.', budget:'Three main simulations and an optional two-run lateness comparison; no ML fits.',
 how:'Emergence describes a pattern at the collective level that arises from component interactions. In this exercise, workers preferentially take jobs similar to their recent work, reducing a synthetic setup cost. Groups of similar jobs can form without a central grouping plan. This is a small operational example, not evidence of consciousness or general intelligence.', predict:'Will the clustering persist if workers ignore recent jobs?',
 steps:[['Specify the pattern','Choose an observable collective property.','Extend the synthetic queue with job types and a fixed local preference for the previous type. Define a clustering statistic before running. Keep the job list fixed.','The claimed pattern has a measurement.'],['Remove the interaction','Test dependence on local rules.','Compare the preference rule with a rule that ignores job type and one that randomizes history using a fixed seed. Save traces and clustering values. Label every result as simulation.','The ablation tests whether the interaction drives the pattern.']],
 check:'The pattern is defined before measurement. Local rules and global statistic are distinct. Claims remain limited to the simulation.', change:'For the optional counterexample, declare one urgent-job fixture and run it twice: once with FIFO and once with local preference. Keep both traces and compare grouping with lateness. Explain how a visible pattern can be undesirable without replacing the three main cases.', takeaways:['A collective pattern is not automatically a capability gain.','Ablations can test which interactions generate a pattern.','Define what “emergent” refers to in the specific experiment.'],
 quiz:[['What is the system-level property here?','Measured grouping of similar job types across the execution trace.'],['Was that grouping centrally specified?','The local preference is specified; the resulting sequence arises through interactions with available jobs.'],['Does emergence imply self-improvement?','No. The pattern may have no benefit or may be harmful.'],['What would weaken the causal explanation?','The same pattern persisting when the proposed interaction is removed, or a confounded comparison.']], next:'Use a small game to observe experience, feedback, and a retained self-play learning update.'}),
L('07.07','self_play','Learn what self-play does and does not provide',{
 build:'A tiny tic-tac-toe player that learns from self-play, a saved policy table, and a frozen comparison with its untrained version.', why:'Interaction is only one part of self-play learning. You need experience, a feedback source, a parameter update, and a way to judge the resulting policy. A small game makes each part visible on a laptop.', start:'The distinction between retained learning and improved performance. The agent uses the local Python environment and the supplied self-play tool; no extra agent processes are needed.', budget:'3,000 training games plus 500 evaluation games per policy: 4,000 games total, CPU only. Rule tests use separate tiny fixtures. No LLM weights change.', time:'30–45',
 how:'A policy is a rule for choosing an action. Here its parameters are numbers in a table indexed by board, player, and move. Both sides use the same table while playing tic-tac-toe. After a game, each visited move receives its player’s terminal return: +1 for a win, 0 for a draw, or −1 for a loss. Move the stored value one fifth of the way toward that return. This is a tabular Monte Carlo update; it does not use a neural network or a next-state value estimate. With probability 0.2, a training move explores a random legal action. Otherwise it chooses a highest-valued move, breaking ties randomly. The game rules provide feedback. Freeze the learned table before testing it against a random opponent. The table changes; the training algorithm does not. Regression and classification remain the main course project. This short game exposes the self-play mechanism directly.', predict:'If two players interact but no table values change, what has been learned?',
 steps:[['Fix the game and comparison','Keep evaluation choices outside the learning loop.','Read rsi/tools/self_play.py and the self-play section of rsi/tools/README.md. Save the fixed protocol in my lab workspace: 3,000 training games, seed 17, exploration 0.2, learning rate 0.2, and 500 frozen games per policy with equal X/O seats. Keep the supplied evaluation seed schedules. Explain legal moves, terminal returns, and the untrained zero table. Run the small game-rule and learning-boundary tests; retain their result separately.','The game outcome and update rule have precise meanings before training.'],['Run actual self-play learning','Inspect a parameter change caused by a game.','Use the supplied self-play tool to execute this fixed experiment in a new folder in my workspace. Keep all training moves, value updates, episode outcomes, table files, and evaluation traces. Apply a 60-second command limit. Preserve a failed run instead of overwriting it. Show one winning and one losing player update from the saved trace.','Both players generate experience; their terminal returns change stored action values.'],['Inspect the frozen comparison','Separate learning from measured benefit.','Read evaluation-counts.csv and evaluation-policy-hashes.csv. Confirm 500 games per policy and equal X/O seats. Show wins, draws, and losses overall and by seat. Verify the policy hashes do not change during evaluation. Plot these measured counts and identify a remaining trained-policy loss. Do not tune the table or training choices after these results.','The untrained policy interacts without learning. The trained policy uses retained values without changing them during the test.'],['Name the mechanism','Keep the claim tied to the mutable object.','Write SELF-PLAY-REPORT.md: what generated experience, what supplied feedback, what changed, what stayed fixed, and what the comparison supports. Contrast this with a proposer–critic exchange that saves only dialogue. Explain why this run is self-play learning but does not revise its own learning procedure.','A changed policy and a changed improver are different experiments.']],
 check:'All 4,000 experiment games are retained. The table has actual updates, legal game traces, and unchanged evaluation hashes. Both policies use the declared evaluation schedules. The report separates this one measured comparison from claims about optimal play, other tasks, or RSI.', change:'Inspect the untrained baseline: it plays 500 games but retains no parameter changes. Explain why more interaction alone would not train it. Then propose, without running, a comparison against a stronger opponent and state which earlier claim that would test.', takeaways:['Self-play supplies experience that a declared learning rule can use.','A saved parameter change shows learning; a fair comparison tests benefit.','A fixed self-play trainer can improve a policy without recursive self-improvement.'],
 quiz:[['Where is the learning in this run?','The after-game update changes retained state-action values using each player’s terminal return. The saved trace exposes those actual parameter changes.'],['Why is the untrained baseline a useful counterexample?','It interacts with an opponent during evaluation but receives no updates. Experience and learning are separate mechanisms.'],['Does a higher win count against random play prove optimal play?','No. It measures performance against that opponent and schedule. A stronger opponent or a different seat can expose failures.'],['What would have to change to investigate RSI?','The procedure that produces improvements would need a justified revision that is inherited by later improvement work and judged under a fixed external comparison. Updating the policy table under this unchanged trainer does not do that.']],
 source:'[SQL-Zero, 4 September 2026](https://arxiv.org/html/2609.04697v1), offers a recent contrast: a challenger generates tasks, database execution supplies feedback, and alternating GRPO steps update the challenger and solver.',
 adaptation:'The lab retains self-generated interaction, executable outcome feedback, and actual parameter updates. Its tabular game omits SQL generation, learned curricula, LLM weights, and GRPO. It does not reproduce SQL-Zero. Inspect the author’s full run at [self-play evidence](../../evidence/2026-09-20/self-play/README.md); your own result must come from your own run.',
 next:'Allow a system to edit its own procedure, then ask whether the edit helps.'}),
L('07.08','modification','Make a self-modification inspectable',{
 build:'A versioned edit to a learner-owned procedure with tests and rollback.', why:'Writing a change is a capability. Improving the system is a separate result.', start:'A learner-owned task skill and its passing and failing cases. Preserve canonical course files.', budget:'One edit; two cases checked under both parent and child instructions. At most two new fits in total; use saved predictions when fitting is unnecessary.',
 how:'Self-modification means the system changes part of its own implementation or instructions. The target can be a prompt, skill, tool, route, or model parameters. The name says what can change, not whether the change is good. Versioning and rollback make the consequence inspectable.', predict:'Can a modification make the system worse while still being genuine self-modification?',
 steps:[['Apply one bounded edit','Identify the mutable surface.','Ask the current agent to revise one learner-owned task skill using a recorded failure. Preserve parent and child versions, explain the changed instruction, and keep the evaluator fixed.','The change has a clear target and ancestry.'],['Check and roll back if needed','Separate modification from acceptance.','Run the relevant passing and failing cases. Use the declared acceptance rule. If the child regresses, restore the parent as active while keeping the child and its evidence.','A rejection is retained as part of the history.']],
 check:'The changed surface, parent, child, checks, and active version are recorded. The outcome does not receive an automatic improvement label.', change:'Propose deleting a check to make more candidates pass. Explain why that changes acceptance rather than demonstrating better task performance.', takeaways:['Self-modification describes a change mechanism.','Improvement requires an evaluation beyond the edit itself.','Rollback preserves a usable system without erasing evidence.'],
 quiz:[['Is every self-modification an improvement?','No. It can be neutral, harmful, or invalid.'],['Does changing a prompt train model weights?','No. It changes an external instruction surface.'],['Why keep the evaluator fixed?','Otherwise apparent improvement may come from weakening the definition of success.'],['When does recursion enter?','When an improvement procedure itself changes and that changed procedure governs later improvement work.']], next:'You can name the mechanisms. Now strengthen the comparisons used to judge them.'}),
L('08.01','repeat_measurement','Distinguish a result from a reliable comparison',{
 build:'A repeated comparison with paired seeds and an explicit uncertainty statement.', why:'One favorable result can reflect randomness or a convenient sample. Repetition helps reveal instability.', start:'Two frozen model recipes and one fixed task contract.', budget:'Six fits: three paired seeds for two small tree-based recipes. No seed selection after results.',
 how:'Use the same prespecified seeds for both recipes. Compare paired differences, retain all runs, and report their spread. Three seeds are a small demonstration, not a precise population estimate. Deterministic recipes may show no seed variation; that does not eliminate uncertainty from data choice.', predict:'If all three differences favor one recipe, what uncertainty remains?',
 steps:[['Predeclare repetitions','Prevent favorable seed selection.','Write a plan comparing tree and forest on calendar inputs with seeds 17, 29, and 43. Fix the split and metric. Explain that model and complexity differ and that the goal is stability of this comparison.','Every planned run is named before results.'],['Run and summarize','Show the whole distribution of outcomes.','Execute all six fits in separate or compatible bounded workspaces. Report paired MAE differences, mean, range, and total measured fit time. Generate a plot from actual values. Do not claim statistical certainty from three seeds.','The report includes unfavorable pairs as well as favorable ones.']],
 check:'All six planned runs appear, or missing runs are explained. No seed is discarded. Uncertainty includes task and data limitations.', change:'Calculate how the conclusion changes if only the best seed is shown. Label that selection as misleading.', takeaways:['Repeated paired comparisons expose some variability.','Best-run reporting hides selection opportunities.','Seed stability does not establish task generality.'],
 quiz:[['Why pair seeds?','It makes the comparison conditions more similar and can reduce irrelevant variation.'],['Can three seeds prove a universal gain?','No. They provide a small stability check on one task and split.'],['What if predictions are identical across seeds?','The recipe may be deterministic; uncertainty from datasets and task choice remains.'],['Why count failed runs?','They consume resources and affect reliability, even without a valid score.']], next:'Separate selection feedback from the final check.'}),
L('08.02','final_boundary','Freeze selection before final evaluation',{
 workspaceNote:'Use 08-02 for the selection decision and lesson notes. Run final evaluation in the original experiment workspace, where its contract and candidate ledger already exist. Do not create a replacement experiment or reset its attempts.',
 build:'A selected recipe evaluated once on the final public partition, with further search closed.', why:'A test repeatedly used to choose changes becomes part of the selection process.', start:'A completed selection ledger and one preselected candidate. Use its original workspace.', budget:'One final evaluation; no subsequent selection in that workspace.',
 how:'Selection chooses a recipe using development feedback. Final evaluation measures that frozen choice on another partition. The local tool locks selection before final scoring. This enforces a workflow for a cooperative agent, but the source remains public and readable. An adversarial or truly hidden evaluation needs separate control.', predict:'What should happen if you request a new candidate after seeing the final score?',
 steps:[['Freeze the choice','Commit before observing final outcomes.','Write SELECTION-DECISION.md with the chosen candidate, recipe, reason, and source contract. Confirm no final results were used to choose it.','The retained object is unambiguous.'],['Evaluate once','Test the lock as well as the score.','Run the supplied final evaluation for that candidate. Inspect FINAL.md and predictions. Then attempt another selection fit and retain the refusal. Do not reopen the workspace.','The score exists and post-final search is blocked.']],
 check:'Final evaluation uses the recorded recipe and original training rows. A later fit request is rejected. The report states that the source is public.', change:'Describe a separate evaluation service where the candidate cannot read cases or edit scoring. List which boundary is stronger than the local exercise.', takeaways:['Data roles depend on how information is used.','Final evaluation follows a frozen choice.','A workflow lock is different from access isolation.'],
 quiz:[['What happens when final feedback guides another edit?','Those cases have become development information for that edit; a fresh final test is needed.'],['Why lock before evaluation rather than after?','An interrupted final run may already expose information. The lock prevents unnoticed reuse.'],['Does a filename called heldout make data secret?','No. Actual permissions and context boundaries determine access.'],['Can the public-data result still be useful?','Yes, as a reproducible teaching comparison with its exposure limits stated.']], next:'Measure the resources used to obtain the retained result.'}),
L('08.03','cost','Count the cost of research',{
 build:'A resource ledger that includes proposals, checks, retries, failed work, and fitting.', why:'A method can look better because it spent more resources outside the model-fit counter.', start:'Two procedure traces and their candidate ledgers.', budget:'No new fits; reconcile existing measurements.',
 how:'Resources are not interchangeable. Record agent tokens or provider charges when available, local fit seconds, total wall time, evaluator calls, and later GPU-hours. Unknown values stay unknown. Equal fit counts are useful but do not imply equal total research cost.', predict:'Which procedure could appear efficient if its failed proposals were omitted?',
 steps:[['Build the ledger','Account for the full route to the result.','Create COST.md for both traces. Include proposal generation, data inspection, fitting, evaluation, review, retries, failures, and final checking. Mark unavailable agent costs explicitly.','No cost category silently becomes zero.'],['Reinterpret the comparison','Match the conclusion to available accounting.','Compare retained quality at matched known resources. State whether total-cost superiority can be assessed. Show the effect of including rejected attempts in the count.','A narrower defensible conclusion may replace an attractive broad claim.']],
 check:'The ledger reconciles every attempt. Unknown cost is distinct from zero. The report states what resource equality was actually achieved.', change:'Add a large proposal-generation cost to a labelled numerical illustration. Determine when a fit-efficient method becomes more expensive overall.', takeaways:['Research overhead can dominate training cost.','Unknown is not zero.','Efficiency claims require a declared quality and resource comparison.'],
 quiz:[['Why count rejected candidates?','They were part of the search cost required to obtain the retained artifact.'],['Can tokens be converted to GPU-hours without assumptions?','No. They measure different resources and require a specified pricing or compute model to combine.'],['What if provider usage is unavailable?','Report the gap and restrict the cost claim.'],['Does a higher score at ten times the budget prove a better method?','It may show a better result at that budget, not superior efficiency or equal-resource performance.']], next:'Use controlled removals to ask which change caused a benefit.'}),
L('08.04','ablation','Separate the effects of memory and procedure changes',{
 build:'A small factorial comparison of memory and a task-skill revision.', why:'Changing two components at once makes it hard to know which helped or harmed.', start:'A frozen memory note, parent skill, child skill, and prespecified task fixtures.', budget:'Four arms with one fit each, or four executable fixture checks if fitting is unnecessary.',
 how:'Compare parent without memory, parent with memory, child without memory, and child with memory. The combined effect can differ from the sum of separate effects. Keep starting state and resources matched. This tests the selected components on selected tasks, not all possible memories or skills.', predict:'Could useful memory become harmful when paired with a changed skill?',
 steps:[['Declare four arms','Separate main effects and interaction.','Write ABLATION-PLAN.md with the four component combinations, same task, same budget, and fixed acceptance metric. Identify possible conflicting instructions.','Each arm answers a distinct comparison.'],['Execute the comparison','Retain interactions and failures.','Run all arms from clean starting state where possible. Record context boundaries, actual decisions, results, and costs. Explain whether the combination behaves differently from the individual changes.','A component’s effect can depend on the other component.']],
 check:'All arms are present and differ only in declared components. Shared-context limitations are stated. No favorable arm is relabelled as the only planned comparison.', change:'Remove a conflicting memory rule in a separately declared follow-up. Do not merge that new result into the original experiment.', takeaways:['Ablations help attribute an observed effect.','Components can interact.','Follow-up hypotheses need new records.'],
 quiz:[['Why use four arms instead of two?','They separate the effects of memory, skill change, and their combination.'],['What is an interaction here?','The effect of one component changes depending on whether the other is present.'],['Does a small ablation identify every cause?','No. It addresses the controlled components and can still have context or sampling confounds.'],['Why preserve an arm that crashes?','Reliability is part of the outcome and its resource use remains part of the comparison.']], next:'Freeze a retained skill and test a task it did not help select.'}),
L('08.05','transfer','Test whether the lesson transfers',{
 build:'A transfer report that applies a frozen research skill to wine classification.', why:'A procedure tuned on one regression dataset may encode assumptions that fail elsewhere.', start:'A selected frozen research skill and the wine task brief. No wine results used to write that skill.', budget:'Four wine fits: two per parent and child procedure.',
 how:'Transfer asks whether a retained change helps in a different setting. Keep the skill frozen while adapting only task-specific interfaces required by the brief. Record any necessary adaptation. If you rewrite the skill after seeing wine outcomes, that becomes wine development, not the original transfer test.', predict:'Which bike-specific advice could fail on imbalanced classification?',
 steps:[['Freeze and map','Separate general procedure from task-specific facts.','Record parent and child hashes. Map their instructions to the wine task without reading new results. Flag bike-specific assumptions, such as minimizing MAE, before execution.','The transfer conditions are explicit.'],['Run both procedures','Observe generalization and negative transfer.','Give each procedure two wine fits under the same classification contract. Compare retained balanced accuracy, both class recalls, decisions, and costs. Keep any failed transfer.','A useful regression procedure can be neutral or harmful here.']],
 check:'The procedure version is frozen before wine outcomes. Task-interface changes are documented. The result is not used to rewrite the original claim retroactively.', change:'Use the observed failure to propose a new skill version, but label its evaluation as a new development round requiring fresh transfer cases.', takeaways:['Transfer tests the scope of a retained lesson.','Necessary interface adaptation must be visible.','Negative transfer is informative evidence.'],
 quiz:[['Why freeze the skill first?','Otherwise the transfer cases can influence the candidate being tested.'],['Can a metric name be adapted without changing the research principle?','Sometimes, if that interface adaptation is declared before results and the principle remains fixed.'],['Does failure on wine invalidate the bike result?','No. It limits the result’s scope and reveals a transfer problem.'],['What follows a transfer-informed edit?','A new version and a new evaluation on cases not used for that edit.']], next:'Practice rejecting an apparent improvement produced by a misleading metric.'}),
L('08.06','rollback','Reject a misleading win and roll back',{
 build:'A promotion decision that rejects a superficially strong but invalid candidate.', why:'A reliable improvement system must preserve its definition of success when a tempting result appears.', start:'The wine baseline and a labelled report that emphasizes accuracy while omitting positive recall.', budget:'No new fits if predictions exist; one metric recomputation.',
 how:'A majority classifier can be accurate on imbalanced data while detecting no positive cases. The declared primary metric is balanced accuracy. Changing the promotion metric after observing results creates a different experiment. Rollback restores the retained valid version while preserving the rejected proposal and evidence.', predict:'Should a candidate with high ordinary accuracy but zero positive recall be promoted under the declared rule?',
 steps:[['Audit the win','Recompute the metric that was promised.','Calculate ordinary accuracy, both class recalls, and balanced accuracy from the majority baseline predictions. Compare the promotional summary with the task contract.','The apparently strong accuracy coexists with balanced accuracy 0.5.'],['Reject and restore','Keep the evidence while restoring the active version.','Write PROMOTION.md rejecting any unsupported metric-switch claim. Restore the previously valid active skill or recipe if it was replaced in the fixture. Keep the rejected version, reason, and cost.','Rollback changes the active choice without erasing history.']],
 check:'The decision uses the predeclared metric and validity rules. Rejected artifacts remain available. No performance claim comes from changing the evaluator.', change:'Create a genuinely new task where overall accuracy is the chosen objective. Explain why its results belong in a separate record with a stated tradeoff.', takeaways:['A metric switch can manufacture an apparent gain.','Promotion rules should precede results.','Rollback and retained failures are part of reliable improvement.'],
 quiz:[['Why can majority accuracy be high?','Most rows belong to one class, so predicting it often is correct despite failing the minority.'],['What does balanced accuracy expose?','The average of class recalls, including zero recall for the ignored class.'],['Can the objective ever change legitimately?','Yes, through a new declared task or protocol, not an unnoticed post-result switch.'],['Does rejecting a candidate mean the system failed?','No. Correct rejection can show that its evaluation and retention process worked.']], next:'Use these evidence rules to distinguish solver improvement from improvement of the improver.'}),
L('09.01','three_objects','Identify the solver, improver, and evaluator',{
 build:'A map of three distinct components and the changes each may make.', why:'“The system improved itself” is too vague to inspect until you identify the system boundary and mutable object.', start:'The task skill, fixed improver, evaluator contract, and version history.', budget:'No fits. One component and permission map.',
 how:'The solver runs ML research. The improver proposes and tests changes to the solver’s procedure. The external evaluator measures outcomes under fixed rules. An improver may change its internal proposal-ranking or promotion rule; that changed procedure is still judged by the unchanged external comparison. Recursion concerns changes to an improvement procedure that later participates in improvement. An extra loop around a solver does not establish that relationship by itself.', predict:'If only a tree depth changes, which component has changed?',
 steps:[['Draw the boundaries','Name the objects before classifying the result.','Create COMPONENTS.md with solver, improver, evaluator, inputs, outputs, writable artifacts, and version hashes. Identify who or what currently supplies each role.','The word self has an explicit referent.'],['Classify three changes','Test the map on concrete examples.','Classify a new model setting, a revised task skill, and a revised improver rule. For each state what later behavior would need to change and what evidence would show it.','The three edits support different claims.']],
 check:'The evaluator is outside the ordinary mutable surface. The map distinguishes host model, task model, task skill, and improver procedure.', change:'In a labelled diagram, let a candidate change the external final metric after seeing its result. Explain why that invalidates the comparison. Contrast it with a candidate improver changing its internal proposal-selection rule while the external metric, final cases, and resource budget stay fixed.', takeaways:['Name the mutable object before naming the mechanism.','The task model and the coding agent are different models.','Evaluation rules must remain stable for the claimed comparison.'],
 quiz:[['Is changing tree depth recursive improvement?','It is ordinary task-model search under the current procedure.'],['What does a revised task skill change?','How the solver carries out future task work.'],['What does a revised improver change?','How later procedure improvements are proposed, tested, allocated, or retained.'],['Why keep evaluation separate?','Otherwise a system can appear better by changing the external measurement or final acceptance criterion. Internal candidate-selection rules may change if the unchanged external evaluator judges the resulting procedure.']], next:'Establish the fixed-improver baseline before letting that procedure change.'}),
L('09.02','fixed_improver','Run repeated improvement with an unchanged improver',{
 build:'Two generations of task-skill revision governed by one fixed improver.', why:'Repeated self-improvement is the comparison baseline for recursive improvement, not proof of it.', start:'A parent task skill, one fixed improver version, and development cases.', budget:'Two generations, at most two fits per generation. Include proposal and checking costs.',
 how:'Generation labels track ancestry. The improver reads a solver’s failures, proposes a child task skill, and applies the same acceptance procedure each time. The solver may change repeatedly while the improver remains identical. Numbering generations does not change that fact.', predict:'Can the solver improve twice without the improver improving at all?',
 steps:[['Freeze the improver','Make the baseline identifiable.','Save IMPROVER-v0.md and its hash. Predeclare two generations and a two-fit budget for each. Write the task-skill acceptance rule and permitted changes.','The control procedure is fixed before the run.'],['Run two generations','Preserve all proposals and decisions.','Use the same improver for both rounds. Save each parent and child skill, proposal, evaluation, rejection or promotion, and costs. Verify the improver hash stays unchanged.','The lineage can show repeated solver changes under a fixed method.']],
 check:'Both rounds use the same improver. Every retained task skill has a corresponding evaluation. The conclusion says repeated self-improvement, not automatically RSI.', change:'Use a rejected child as the next parent in a labelled diagnostic replay. Explain why that would contradict the recorded promotion policy.', takeaways:['Generations describe history, not necessarily recursion.','A fixed improver can produce many solver revisions.','Ancestry should follow actual promotion decisions.'],
 quiz:[['Which version stays fixed?','The improver procedure.'],['What can improve over generations here?','The task skill and resulting solver behavior, if measurements support it.'],['Does persistence of a child establish its benefit?','No. Persistence and evaluation are distinct.'],['Why retain failed proposals?','They show the complete search and resource use behind the selected lineage.']], next:'Use the baseline’s failures to propose a change to the improver itself.'}),
L('09.03','revise_improver','Propose a change to the improver',{
 build:'A child improver that changes how future task-skill revisions are chosen or tested.', why:'To improve the improvement process, the target of an edit must reach that process.', start:'The fixed-improver lineage and its complete failure records.', budget:'One improver proposal and two small procedural checks; no broad search.',
 how:'Suppose the fixed improver promotes a skill after one favorable case and misses a known regression. A candidate improver can require a contrasting case before promotion. This changes the procedure for improving task skills. Its internal promotion rule is a legitimate target; the external cases, metric, and comparison budget used to judge that change stay fixed. The proposal remains a hypothesis until it governs later work and receives a fair comparison.', predict:'Could an extra regression check improve reliability while reducing the number of proposals tried?',
 steps:[['Diagnose the improver','Target a procedural failure rather than a model setting.','Use the full lineage to identify one weakness in IMPROVER-v0. Write a proposal changing one diagnosis, proposal, allocation, or selection rule. State its expected benefit, overhead, and falsifying case.','The mutable target is the improvement procedure.'],['Create the child','Preserve a runnable version.','Save IMPROVER-v1.md without overwriting v0. Test its instructions on one favorable and one regressing fixture. Keep the evaluator unchanged and record the changed decision.','The candidate improver has a concrete behavioral difference.']],
 check:'The edit affects future skill improvement. Parent and child remain available. The report does not claim effectiveness from text quality alone.', change:'Compare “write more thoughtful proposals” with “test a contrasting case before promotion.” Explain which is easier to inspect and falsify.', takeaways:['An improver revision targets how improvements are produced.','Added checks have resource costs.','A better-looking procedure is still an unproven candidate.'],
 quiz:[['Why is this more than a task-model change?','It changes how later task-skill changes are evaluated or selected.'],['What does the fixture test establish?','That the new instruction can produce the intended decision difference on those fixtures.'],['Does that prove a better improver?','No. Later matched comparisons are still required.'],['What must remain outside the edit?','The evaluation contract used to judge the proposed improvement.']], next:'Make the next improvement round actually inherit the child procedure.'}),
L('09.04','inherit','Use the revised improver in the next round',{
 build:'An inheritance trace from a changed improver to a later task-skill proposal and decision.', why:'A saved new improver can remain unused while the system silently follows the old procedure.', start:'IMPROVER-v0, IMPROVER-v1, a fresh parent task skill, and new development cases.', budget:'One later improvement round, at most two fits or equivalent fixture evaluations.',
 how:'Structural recursion requires a path from a procedure revision into later improvement work. Record the inherited version and show a decision caused by its changed rule. A hash proves identity, not obedience. The trace must connect the rule to an executed proposal or check.', predict:'What would show that the new regression-check rule actually governed the next round?',
 steps:[['Start from the inherited version','Make selection explicit.','Read IMPROVER-v1 as the active improvement procedure. Save its hash and parent link. Create a fresh round with the same external evaluator rules and the declared budget.','The active procedure is unambiguous.'],['Observe the changed action','Trace instructions into later improvement.','Use v1 to propose and evaluate a new task-skill revision. Record the contrasting-case check it requires, its actual result, and the promotion decision. State whether v0 would have required the same action.','The inherited rule affects an executed improvement step.']],
 check:'The trace includes version identity and an observed decision difference. Merely copying the new file is not accepted as proof of use.', change:'Replace the active pointer with v0 in a labelled dry run. Identify which action should disappear and which evaluation rules remain fixed.', takeaways:['Inheritance must reach execution.','File lineage and behavioral evidence complement each other.','Structural recursion does not guarantee beneficial recursion.'],
 quiz:[['What does the hash establish?','Which exact procedure file was selected or recorded.'],['What additional evidence supports use?','An executed decision or check tied to the changed instruction.'],['Can this loop still perform worse?','Yes. A genuinely inherited change can consume more resources or choose worse revisions.'],['What claim is supported before a fair comparison?','A bounded structural recursion demonstration, subject to the actual execution evidence and context limits.']], next:'Compare the original and revised improvers under matched conditions.'}),
L('09.05','compare_improvers','Measure whether the revised improver helps',{
 build:'A matched comparison of improvements produced by two improver versions.', why:'The new improver may produce a strong current solver yet be worse at producing future improvements.', start:'Frozen v0 and v1 improvers, identical parent task skill, and prespecified fresh comparison cases.', budget:'Two rounds per improver, at most two fits per round; eight fits total. Count proposal and check overhead.',
 how:'The outcome is the improvement each procedure produces from the same starting solver under comparable resources. Compare retained descendants, not the most attractive intermediate score. Use fresh contexts where available and state contamination if both procedures share one context. A small experiment can remain inconclusive.', predict:'Could v1 win on the current task but lose on improvement produced per unit cost?',
 steps:[['Freeze the protocol','Define the comparison before execution.','Write IMPROVER-COMPARISON.md with starting skill, tasks, budgets, acceptance rule, repetitions, context boundary, and measured costs. Do not use cases that selected v1 as fresh evidence.','The comparison is about future improvement work.'],['Run both arms','Measure descendants and overhead.','Execute v0 and v1 from matched starting artifacts. Keep all proposals, failed checks, descendants, and costs. Compare retained gains over the common baseline and report uncertainty. If fresh independent contexts are unavailable, label that limitation prominently.','The evidence can show benefit, regression, or insufficient information.']],
 check:'Both arms start from the same solver. Their resource limits and known costs are reported. The conclusion concerns the tested improvers and tasks only.', change:'Show how reporting only the best child from each arm hides failed proposals and selection cost.', takeaways:['A better solver is not automatically a better improver.','Measure gains produced from comparable starts.','Retained descendants and total research costs matter.'],
 quiz:[['What is the main dependent outcome?','The improvement produced by each improver under the declared comparison, together with its cost and reliability.'],['Why use fresh cases?','Cases used to design or select v1 can favor it and weaken the generalization claim.'],['Does one win establish sustained acceleration?','No. That requires repeated generational evidence beyond a two-version comparison.'],['What if total agent cost is unknown?','State it and avoid claiming equal total-resource superiority.']], next:'Run a short lineage with checkpoints and a stopping rule.'}),
L('09.06','bounded_generations','Run bounded recursive generations',{
 build:'A two-generation recursive lineage with promotion, rejection, checkpoint, and stop records.', why:'Recursion without explicit scope can turn into unlimited search or an unreadable history.', start:'The tested improver versions, fixed evaluation protocol, and clean generation folders.', budget:'Two generations maximum; four fits per generation including comparisons. No automatic extension.',
 how:'Each generation records the active solver, active improver, proposal, evaluation, retained versions, and spent resources. The next generation inherits only the selected versions. A rejected change remains in the archive but does not become the active parent. Stop when the budget ends even if the last result is disappointing.', predict:'What should the next generation inherit after an improver proposal is rejected?',
 steps:[['Declare the lineage','Make inheritance and limits explicit.','Create LINEAGE.md with two generation slots, solver and improver parent IDs, acceptance rules, cumulative budget, and stop conditions. Keep evaluator version fixed.','The plan distinguishes proposed from active descendants.'],['Execute and checkpoint','Keep every transition reviewable.','Run the bounded generations using the selected active improver. Save proposals, checks, costs, and promotion decisions. At each boundary write PROGRESS.md. Stop at the declared limit and audit inherited versions.','The lineage records both successful and rejected changes.']],
 check:'No hidden extra generation runs. Rejected versions do not become active accidentally. The total ledger includes all attempts and known costs.', change:'Interrupt after a proposal but before promotion. Explain which version is active on resume and which evidence is still missing.', takeaways:['Recursion needs the same state and budget discipline as simpler loops.','Proposal and promotion are different events.','A stopped lineage can be scientifically useful without improvement.'],
 quiz:[['What follows a rejected improver?','The previously retained improver remains active unless another declared decision changes it.'],['Why track solver and improver versions separately?','They can change independently and support different claims.'],['Can the budget reset every generation?','Only if the original total protocol explicitly allocates it that way; spent global resources do not vanish.'],['What if interrupted before acceptance?','Keep the proposal unpromoted and resume the missing check or stop, using the last accepted active versions.']], next:'Classify the strongest claim the complete experiment supports.'}),
L('09.07','claim','State the result without overstating it',{
 build:'A final claim audit separating structural recursion, effective improvement, and acceleration.', why:'The strongest-looking label is less useful than a conclusion another researcher can verify.', start:'The complete lineage, matched comparison, costs, failures, and boundary notes.', budget:'No fits. One evidence audit and one teach-back.',
 how:'Structural recursion means a changed improvement procedure enters later improvement work. Effective recursive improvement adds evidence that this change improves the improvement process under the comparison. Acceleration asks whether progress itself grows across generations after accounting for resources and bottlenecks. These are progressively stronger claims, not automatic consequences.', predict:'Which of these claims would survive if the inherited improver made every later result worse?',
 steps:[['Audit the evidence','Match each claim to its necessary observation.','Use audit-rsi-claim on the complete experiment. Write CLAIM-AUDIT.md with supported claim, missing evidence, costs, context limits, negative results, and one plausible alternative explanation.','The conclusion may stop at structure or report no effective improvement.'],['Teach it back','Test whether the distinction transfers.','Ask me to explain three new cases: repeated model search, persistent memory under a fixed updater, and an inherited improver that loses a matched comparison. Give hints before answers and record unattempted responses honestly.','The explanation identifies what changed and what evidence is missing.']],
 check:'Every claimed level has a corresponding artifact and measurement. Acceleration is not inferred from two favorable points. The audit states public-data and context limits.', change:'Remove the inheritance trace from a copy of the evidence pack. Identify which claim becomes unsupported even if the final task score stays high.', takeaways:['Structure, benefit, and acceleration need different evidence.','A negative result can still demonstrate a real mechanism.','Precise limits make a claim more useful to others.'],
 quiz:[['Can harmful recursion still be structurally recursive?','Yes. The inherited procedure can change later improvement work while degrading its results.'],['What does a high final task score alone establish?','Performance of that retained artifact under its evaluation conditions, not the quality of the improver.'],['Why are two rising points weak acceleration evidence?','They do not establish a sustained rate change or rule out resource and task differences.'],['What is a useful next experiment?','The smallest controlled comparison that addresses the most important missing evidence identified in the audit.']], next:'Use this framework to read current research and rebuild its mechanisms on small tasks.'}),
];
